/**
 * Delegated session keys (ADR-059 D13 §4). The key pair is generated by WebCrypto with a non-extractable private
 * key and kept in IndexedDB (structured clone keeps it non-extractable), so the wallet's key never leaves the wallet
 * and the session key never leaves this browser profile. A lost or stolen session key is bounded by its grant's
 * limits and expiry and ends when the owner revokes the grant.
 */
const DB = 'yano-payments-client';
const STORE = 'session-keys';

export interface StoredSession {
  id: string;
  chainId: string;
  accountId: string;
  grantId: string;
  publicKeyHex: string;
  privateKey: CryptoKey;
  notAfterMs: number;
  createdAtMs: number;
}

/** The longest validity this client grants a session key: a stolen browser key is bounded in time too. */
export const MAX_SESSION_VALIDITY_MS = 24 * 3_600_000;

/**
 * Whether a local session key can be deleted: it has expired, or its grant is no longer committed although its
 * AUTHORIZE_SESSION intent has a receipt (rejected, or accepted and since revoked or replaced), or that intent can no
 * longer execute (its envelope expired without a receipt). A key whose intent is still pending is kept.
 */
export function isStale(session: StoredSession, committedGrants: Set<string>, receiptFound: boolean | undefined,
                        nowMs: number, maxIntentTtlMs: number): boolean {
  if (session.notAfterMs <= nowMs) return true;
  if (committedGrants.has(session.grantId)) return false;
  if (receiptFound === true) return true;
  return session.createdAtMs + maxIntentTtlMs + 60_000 < nowMs;
}

export async function ed25519Supported(): Promise<boolean> {
  try {
    await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
    return true;
  } catch {
    return false;
  }
}

export async function generateSessionKey(): Promise<{ privateKey: CryptoKey; publicKey: Uint8Array }> {
  const pair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair;
  const publicKey = new Uint8Array(await crypto.subtle.exportKey('raw', pair.publicKey));
  return { privateKey: pair.privateKey, publicKey };
}

export async function signWithSession(privateKey: CryptoKey, envelope: Uint8Array): Promise<Uint8Array> {
  return new Uint8Array(await crypto.subtle.sign('Ed25519', privateKey, new Uint8Array(envelope)));
}

const memory = new Map<string, StoredSession>();

function open(): Promise<IDBDatabase | null> {
  return new Promise((resolve) => {
    try {
      const request = indexedDB.open(DB, 1);
      request.onupgradeneeded = () => request.result.createObjectStore(STORE, { keyPath: 'id' });
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
}

export async function saveSession(session: StoredSession): Promise<boolean> {
  memory.set(session.id, session);
  const db = await open();
  if (!db) return false;
  return new Promise((resolve) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(session);
    tx.oncomplete = () => resolve(true);
    tx.onerror = () => resolve(false);
  });
}

export async function listSessions(chainId: string, accountId: string): Promise<StoredSession[]> {
  const db = await open();
  const all: StoredSession[] = db ? await new Promise((resolve) => {
    const request = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    request.onsuccess = () => resolve(request.result as StoredSession[]);
    request.onerror = () => resolve([]);
  }) : [...memory.values()];
  return all.filter((session) => session.chainId === chainId && session.accountId === accountId);
}

export async function deleteSession(id: string): Promise<void> {
  memory.delete(id);
  const db = await open();
  if (!db) return;
  await new Promise<void>((resolve) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => resolve();
  });
}
